// Edit these two lines, or POST {"listing": "steinmann-106"} to the webhook.
const repo = '/mnt/llm/listing-heroes';
const listing = ($json.body && $json.body.listing) || $json.listing || 'steinmann-106';
return [{ json: { repo, listing } }];

// Gather everything the copy steps need: repo, listing, prompts, and absolute photo/output folders.
const repo = $('Config').first().json.repo;
const listing = $('Parse listing').first().json.data;
const prompts = $input.first().json.data;
const base = `${repo}/pipeline/listings`;
const resolve = (rel) => {
  const parts = (rel.startsWith('/') ? rel : `${base}/${rel}`).split('/');
  const out = [];
  for (const s of parts) { if (s === '..') out.pop(); else if (s && s !== '.') out.push(s); }
  return '/' + out.join('/');
};
return [{ json: { repo, listing, prompts, photos: resolve(listing.photos_dir), out_dir: resolve(listing.out_dir) } }];

// One item per room in the listing file, with the photo's absolute path.
const c = $input.first().json;
return c.listing.rooms.map((r) => ({ json: { room: r.room, photo: r.photo, path: `${c.photos}/${r.photo}.jpg` } }));

// Build the Messages API request that drafts room-by-room copy from the room photos + MLS facts.
// Run once for all items. Items come from "Read room photos" (binary.data = the photo, json.room/photo).
const cfg = $('Copy config').first().json;           // { prompts, listing }
const P = cfg.prompts, L = cfg.listing;
const content = [{ type: 'text', text: `Listing: ${L.address}\nMLS facts:\n${JSON.stringify(L.facts, null, 2)}\n\nOne photo per room follows.` }];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  content.push({ type: 'text', text: `Room: ${it.json.room} (photo id: ${it.json.photo})` });
  content.push({ type: 'image', source: { type: 'base64', media_type: it.binary.data.mimeType || 'image/jpeg', data: buf.toString('base64') } });
}
content.push({ type: 'text', text: 'Write the copy for every room above, in the same order, using each photo id as given. Also write a 6 to 10 word headline and a 2 sentence summary for the top of the page.' });
const body = {
  model: P.model,
  max_tokens: 16000,
  fallbacks: 'default',
  output_config: { effort: 'medium', format: { type: 'json_schema', schema: P.draft_schema } },
  system: P.draft_system,
  messages: [{ role: 'user', content }],
};
return [{ json: { body } }];

// Pull the JSON answer out of a Messages API response; fail loudly on refusal or truncation.
const r = $input.item.json;
if (r.type === 'error') throw new Error(`Claude API error: ${r.error && r.error.type}: ${r.error && r.error.message}`);
if (r.stop_reason === 'refusal') throw new Error(`Claude declined (${(r.stop_details || {}).category || 'no category'}): ${(r.stop_details || {}).explanation || ''}`);
if (r.stop_reason === 'max_tokens') throw new Error('Claude hit max_tokens before finishing; raise max_tokens');
const text = (r.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
return { json: Object.assign(JSON.parse(text), { _usage: r.usage, _model: r.model }) };

// Build the fair-housing / accuracy review request for the drafted copy.
const P = $('Copy config').first().json.prompts, L = $('Copy config').first().json.listing;
const draft = $input.first().json;
const body = {
  model: P.model,
  max_tokens: 16000,
  fallbacks: 'default',
  output_config: { effort: 'high', format: { type: 'json_schema', schema: P.check_schema } },
  system: P.check_system,
  messages: [{ role: 'user', content: `Listing: ${L.address}\nMLS facts:\n${JSON.stringify(L.facts, null, 2)}\n\nDraft copy:\n${JSON.stringify({ headline: draft.headline, summary: draft.summary, rooms: draft.rooms }, null, 2)}\n\nReview every room. The headline and summary must pass too; report them with photo "headline" or "summary".` }],
};
return [{ json: { body, draft } }];

// Pull the JSON answer out of a Messages API response; fail loudly on refusal or truncation.
const r = $input.item.json;
if (r.type === 'error') throw new Error(`Claude API error: ${r.error && r.error.type}: ${r.error && r.error.message}`);
if (r.stop_reason === 'refusal') throw new Error(`Claude declined (${(r.stop_details || {}).category || 'no category'}): ${(r.stop_details || {}).explanation || ''}`);
if (r.stop_reason === 'max_tokens') throw new Error('Claude hit max_tokens before finishing; raise max_tokens');
const text = (r.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
return { json: Object.assign(JSON.parse(text), { _usage: r.usage, _model: r.model }) };

// Merge the review into the final rooms file the hero pages read (rooms.json).
const review = $input.first().json;
const draft = $('Build review request').first().json.draft;
const fix = (id, text) => { const i = review.issues.find((x) => x.photo === id); return i ? text.split(i.phrase).join(i.rewrite) : text; };
const out = {
  listing: $('Copy config').first().json.listing.id,
  generated: new Date().toISOString(),
  model: review._model,
  fair_housing_passed_first_draft: review.passes,
  issues_fixed: review.issues,
  headline: fix('headline', draft.headline),
  summary: fix('summary', draft.summary),
  rooms: review.rooms,
  note: 'Drafted with AI from the listing photos and MLS facts, reviewed for fair-housing language. Read it before publishing.',
};
const data = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(out, null, 2)), 'rooms.json', 'application/json');
return [{ json: out, binary: { data } }];
